static inline const ASR_PpEnumFieldDesc *asr_pp_lookup_enum_field(
        const char *field) {
    if (!field) {
        return NULL;
    }
    for (size_t i = 0; i < ASR_PP_ENUM_FIELDS_COUNT; ++i) {
        if (strcmp(field, ASR_PP_ENUM_FIELDS[i].field) == 0) {
            return &ASR_PP_ENUM_FIELDS[i];
        }
    }
    return NULL;
}

static inline bool asr_pp_apply_elide_rule(
        ASR_PpElideKind kind, MLIR_OpHandle op, const char *field) {
    switch (kind) {
    case ASR_PP_ELIDE_ALWAYS:
        return true;
    case ASR_PP_ELIDE_I64_ZERO:
        return asr_get_field_i64(op, field, 0) == 0;
    case ASR_PP_ELIDE_BOOL_FALSE:
        return !asr_get_field_bool(op, field, false);
    case ASR_PP_ELIDE_STR_EMPTY:
        return asr_get_field_str(op, field).size == 0;
    default:
        return false;
    }
}

static inline bool asr_pp_variable_field_is_default(
        const char *field, MLIR_OpHandle op) {
    for (size_t i = 0; i < ASR_PP_VARIABLE_ELIDE_COUNT; ++i) {
        if (strcmp(field, ASR_PP_VARIABLE_ELIDE[i].field) == 0) {
            return asr_pp_apply_elide_rule(
                ASR_PP_VARIABLE_ELIDE[i].kind, op, field);
        }
    }
    return false;
}

static inline const char *asr_pp_enum_field_name(
        const char *field, int64_t v) {
    const ASR_PpEnumFieldDesc *desc = asr_pp_lookup_enum_field(field);
    if (!desc || !desc->name_fn) {
        return NULL;
    }
    return desc->name_fn(v);
}

static inline const char *asr_pp_enum_attr_category(const char *field) {
    const ASR_PpEnumFieldDesc *desc = asr_pp_lookup_enum_field(field);
    if (desc && desc->attr_category) {
        return desc->attr_category;
    }
    return field;
}

/* Format one scalar Variable declaration field (legacy dump line). */
static inline bool asr_pp_format_variable_scalar_field(
        MLIR_OpHandle op, const char *field, char *buf, size_t bufsz) {
    if (!field || !buf || bufsz == 0) {
        return false;
    }
    if (strcmp(field, "abi") == 0) {
        const char *en = asr_pp_enum_field_name(
            field, asr_get_field_i64(op, field, 0));
        if (en) {
            snprintf(buf, bufsz, "  %s = #asr.%s<%s>,", field,
                asr_pp_enum_attr_category(field), en);
            return true;
        }
    }
    if (strcmp(field, "access") == 0) {
        const char *en = asr_pp_enum_field_name(
            field, asr_get_field_i64(op, field, 0));
        if (en) {
            snprintf(buf, bufsz, "  %s = #asr.%s<%s>,", field,
                asr_pp_enum_attr_category(field), en);
            return true;
        }
    }
    if (strcmp(field, "intent") == 0) {
        const char *en = asr_pp_enum_field_name(
            field, asr_get_field_i64(op, field, 0));
        if (en) {
            snprintf(buf, bufsz, "  %s = #asr.%s<%s>,", field,
                asr_pp_enum_attr_category(field), en);
            return true;
        }
    }
    if (strcmp(field, "pass_attr") == 0) {
        const char *en = asr_pp_enum_field_name(
            field, asr_get_field_i64(op, field, 0));
        if (en) {
            snprintf(buf, bufsz, "  %s = #asr.%s<%s>,", field,
                asr_pp_enum_attr_category(field), en);
            return true;
        }
    }
    if (strcmp(field, "presence") == 0) {
        const char *en = asr_pp_enum_field_name(
            field, asr_get_field_i64(op, field, 0));
        if (en) {
            snprintf(buf, bufsz, "  %s = #asr.%s<%s>,", field,
                asr_pp_enum_attr_category(field), en);
            return true;
        }
    }
    if (strcmp(field, "storage") == 0) {
        const char *en = asr_pp_enum_field_name(
            field, asr_get_field_i64(op, field, 0));
        if (en) {
            snprintf(buf, bufsz, "  %s = #asr.%s<%s>,", field,
                asr_pp_enum_attr_category(field), en);
            return true;
        }
    }
    if (strcmp(field, "contiguous_attr") == 0) {
        snprintf(buf, bufsz, "  %s = %s,", field,
            asr_get_field_bool(op, field, false) ? "true" : "false");
        return true;
    }
    if (strcmp(field, "is_protected") == 0) {
        snprintf(buf, bufsz, "  %s = %s,", field,
            asr_get_field_bool(op, field, false) ? "true" : "false");
        return true;
    }
    if (strcmp(field, "is_volatile") == 0) {
        snprintf(buf, bufsz, "  %s = %s,", field,
            asr_get_field_bool(op, field, false) ? "true" : "false");
        return true;
    }
    if (strcmp(field, "target_attr") == 0) {
        snprintf(buf, bufsz, "  %s = %s,", field,
            asr_get_field_bool(op, field, false) ? "true" : "false");
        return true;
    }
    if (strcmp(field, "value_attr") == 0) {
        snprintf(buf, bufsz, "  %s = %s,", field,
            asr_get_field_bool(op, field, false) ? "true" : "false");
        return true;
    }
    if (strcmp(field, "bindc_name") == 0) {
        string s = asr_get_field_str(op, field);
        snprintf(buf, bufsz, "  %s = \"%.*s\",", field,
            (int)s.size, s.str ? s.str : "");
        return true;
    }
    if (strcmp(field, "self_argument") == 0) {
        string s = asr_get_field_str(op, field);
        snprintf(buf, bufsz, "  %s = \"%.*s\",", field,
            (int)s.size, s.str ? s.str : "");
        return true;
    }
    if (strcmp(field, "type_declaration") == 0) {
        string sym = asr_get_field_str(op, field);
        if (sym.size == 0) {
            snprintf(buf, bufsz, "  %s = null,", field);
        } else {
            snprintf(buf, bufsz, "  %s = @%.*s,", field,
                (int)sym.size, sym.str ? sym.str : "");
        }
        return true;
    }
    return false;
}
